    35	// What the incident is worth to the claimant: each reported damage is matched
    36	// to the covered item it refers to, and every match is valued separately.
    37	function incidentValueOf(items: Item[], incident: Incident): number {
    38	  return settledDamagesOf(items, incident.damages).reduce(
    39	    (total, settledDamage) => total + valueOf(settledDamage),
    40	    0,
    41	  );
    42	}
    43	
    44	// How a claim settles against the policy's remaining cap. The office never
    45	// pays more than the cap still allows, so a claim worth more than that is
    46	// reduced to what remains rather than refused, and the cap falls by what the
    47	// office actually paid rather than by what the claim was worth. These two
    48	// decisions move together whenever the office revises its cap rules, and
    49	// neither touches what an incident is worth.
    50	function settleAgainstCap(
    51	  remainingCap: number,
    52	  incidentValue: number,
    53	): ClaimResult {
    54	  const payout = roundAmountPaidInMHPCOsFavour(
    55	    Math.min(incidentValue, remainingCap),
    56	  );
    57	  return { payout, remainingCap: remainingCap - payout };
    58	}
