    60	// Settling an incident against a policy: what the incident is worth to the
    61	// claimant, limited by what the policy's cap still allows.
    62	export function claim(
    63	  items: Item[],
    64	  remainingCap: number,
    65	  incident: Incident,
    66	): ClaimResult {
    67	  admitDamages(incident.damages);
    68	  return settleAgainstCap(remainingCap, incidentValueOf(items, incident));
