     1	// The MHPCO price list: which items the office insures, what each is worth to
     2	// it, and what it charges to insure them. These figures change together
     3	// whenever the office revises its tariff, independently of risk clauses and
     4	// customer discounts.
     5	
     6	export interface Item {
     7	  type: string;
     8	  material?: string;
     9	  cursed?: boolean;
    10	  enchantment?: number;
    11	}
    12	
    13	// One tariff row per main item type the office insures: an item type is in the
    14	// catalogue exactly when it has a row, and a row carries both of its figures.
    15	interface Tariff {
    16	  insuranceValue: number;
    17	  basePremium: number;
    18	}
    19	
    20	const MAIN_ITEM_TARIFFS: Record<string, Tariff> = {
    21	  sword: { insuranceValue: 1000, basePremium: 100 },
    22	  amulet: { insuranceValue: 600, basePremium: 60 },
    23	  staff: { insuranceValue: 800, basePremium: 80 },
    24	  potion: { insuranceValue: 400, basePremium: 40 },
    25	};
    26	
    27	const COMPONENT_TYPES = ["rune", "moonstone"];
    28	const COMPONENT_TARIFF: Tariff = { insuranceValue: 250, basePremium: 25 };
    29	const BLOCK_SIZE = 3;
    30	const BLOCK_BASE_PREMIUM = 60;
    31	
    32	export function isComponent(item: Item): boolean {
    33	  return COMPONENT_TYPES.includes(item.type);
    34	}
    35	
    36	function isMainItem(item: Item): boolean {
    37	  return !isComponent(item);
    38	}
    39	
    40	// The office's catalogue decision: an item type it does not list is not insured
    41	// at all, so neither its premium nor its insurance value can be quoted.
    42	function mainItemTariffOf(item: Item): Tariff {
    43	  const tariff = MAIN_ITEM_TARIFFS[item.type];
    44	  if (tariff === undefined) {
    45	    throw new Error(`The MHPCO does not insure items of type "${item.type}"`);
    46	  }
    47	  return tariff;
    48	}
    49	
    50	function tariffOf(item: Item): Tariff {
    51	  return isComponent(item) ? COMPONENT_TARIFF : mainItemTariffOf(item);
    52	}
    53	
    54	function mainItemsBasePremiumOf(mainItems: Item[]): number {
    55	  return mainItems.reduce(
    56	    (total, item) => total + mainItemTariffOf(item).basePremium,
    57	    0,
    58	  );
    59	}
    60	
    61	// "Alike" components are components of exactly the same type, so 2 runes and
    62	// a moonstone form no building block.
    63	function countsPerAlikeGroup(components: Item[]): number[] {
    64	  const counts = new Map<string, number>();
    65	  for (const component of components) {
    66	    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
    67	  }
    68	  return [...counts.values()];
    69	}
    70	
    71	function alikeComponentsBasePremiumOf(count: number): number {
    72	  return count === BLOCK_SIZE
    73	    ? BLOCK_BASE_PREMIUM
    74	    : count * COMPONENT_TARIFF.basePremium;
    75	}
    76	
    77	function componentsBasePremiumOf(components: Item[]): number {
    78	  return countsPerAlikeGroup(components).reduce(
    79	    (total, count) => total + alikeComponentsBasePremiumOf(count),
    80	    0,
    81	  );
    82	}
    83	
    84	export function policyBasePremiumOf(items: Item[]): number {
    85	  return (
    86	    mainItemsBasePremiumOf(items.filter(isMainItem)) +
    87	    componentsBasePremiumOf(items.filter(isComponent))
    88	  );
    89	}
    90	
    91	// Item-specific modifiers apply to the affected item's own base premium,
    92	// so a component is surcharged on its single-component rate rather than on
    93	// its share of a discounted building block.
    94	export function surchargeableBasePremiumOf(item: Item): number {
    95	  return tariffOf(item).basePremium;
    96	}
